        anki: () => this.addToAnki(card, sentence, void 0, context),
        "anki-edit": () => this.openAnkiNote(button2),
        "anki-merge": () => this.mergeExistingAnkiCard(button2, card, sentence, context),
        grade: () => this.gradeCard(button2, card, sentence),
